rows["541:1555641257"]="엄마를 보러 왔어?$B$B전날 소문을 들었어요$B$B지나 무드클라와 그녀의 아버지 하오한 무드클라가 잘 안 어울리는 거 들었어요!$B$B그는 벨트에서 부른 농부와 결혼하고 싶었지만 그녀는 그것을 원하지 않았다고 그녀는 말했다.$B$B어이야, 요즘은 젊은 여자들 무슨 일이 벌어졌어요?$B$B특히 펑그... 그는 정말 어마어마한 놈이야.$B$B왜 내 아들은 그렇게 예쁘지 않은가?"
rows["541:892828586"]="젠타브라의 머리는 다시 당신에게 반짝이고 눈은 밝고 그녀의 웃음은 그녀의 매개로 넓어집니다.$B$B'그것이 더 큰 야생의 산림이었다 내가 본 적이! 그리고 나에게 전에, 고대 랩터 로는 단지 Zandalari 이야기에서 이야기했다-Gonk, 위대한 사냥꾼! $B$B랩터 영이 나와 이야기했고, 에메랄드 드림이라는 곳으로 영을 데려왔다고 말했습니다. 랩터 영은 에코 섬의 다른 사람들처럼 랄아잔의 마법에 갇혀 있었다. 하지만 고크는 고대 영이 되어, 랄아잔의 우두우를 통해서도 나를 데려오며 영을 데려오게 되었다. "
rows["542:1699280722"]="내가 봤어$B$B마즈, 바다의 여신$B$B내 인생에서 최악의 폭풍. 나는 젊고 경험이 없어 보트를 지나쳤어 모든 것이 어두워졌습니다.$B$B그리고 그녀는 여름 오후처럼 맑은 내 앞에 나타났습니다. 상상할 수 없을 만큼 아름답습니다. 목에 총알과 허리에 진주줄이 있습니다. 그녀는 미소를 짓고 그녀의 희미한 팔을 펼쳐 보았습니다.$B$B다음 기억은, 도그가 날 표면에 누워 있었고 승무원들은 날 배에 끌어들이고 있었는데"
rows["545:490091551"]="간단한 자극 반응 테스트. 보통 제 종류는 아제로스의 문제에 개입하지 않지만, 여기 언'고로에서는 좀 더 직접적인 접근을 할 수 있습니다. 언'고로는 타이탄들의 실험지이기 때문에, 그렇게 할 권리가 있습니다.$b$b예를 들어, 카자고로트가 자신의 창조물 중 하나 가 황화성 온천에 노출되면 어떻게 되는지를 알고 싶어한다고 가정 해 봅시다. 그는 천 년 동안 관찰하고 그 생물이 우연히 넘어져 넘어지는 것을 기다려야 할 수도 있고, 아니면 그 생물을 직접 물에 넣을 수도 있습니다.$b$b언고로에서는 그렇게 할 수 있습니다."
