rows["54:996679658"]="너희 둘이 다 끝나면 내게 돌아오"
rows["54:99741745"]="또 다른 기회는 아무런 영향을 주지 않을거야"
rows["54:999474542"]="이 작전은 너무 느려지고 있어, 그들을 동원해!"
rows["54:99995822"]="태양의 포장을 차지하기 위한 싸움에 대한 소식은?"
rows["554:1100839717"]="미스터리와 기적이 매일 우리를 둘러싸고 있습니다. 단지 페어에서 아닙니다. 우리는 매일의 사업에서 만날 수 있는 기적을 목록으로 작성했습니다. 암흑달 모험가의 가이드는 세계의 기적을 탐색하는 데 도움이 될 것입니다.$b$b가이드 를 가지고 있으면, 당신 은 존재 하고 있다는 것 을 알지 못했던 것 들 을 발견 할 수 있습니다. 과거 에 당연 하게 생각했던 것 들 은 이제 다른 사람 들 이 갈망 하는 보물 입니다.$b$b가이드를 가지고 있어, 신비에 눈을 뜨지 마$b$b가이드를 잃으면 찾아서 무료로 교체할 수 있습니다."
rows["555:947563938"]="금속, 광물 및 돌의 물건들을 만들 수 있습니다. 즉, 병기 무기, 우편 및 판자 중무, 다른 생산 직업에서 사용되는 원료, 그리고 날개 돌과 방패 스피치 같은 장비의 업그레이드.\010매우 숙련 된 수강사들은 자신 의  ⁇  및 장갑 에 보석 슬롯 을 추가 할 수 있으며, 자신 이나 다른 사람 의 벨트 에도 보석 슬롯 이 들어 있을 수 있습니다. 그 다음 이 보석 슬롯 은 마법 으로 된 보석 로 가득 차서 보석 을 더 강력 하게 만들 수 있습니다.\010금속공업은 광산과 잘 어울리는데, 이는 자유와 광물을 직접 수집할 수 있게 해준다."
rows["558:484396315"]="여기 4개의 바람의 계곡에 유명한 스톰스타우트 맥주 공장도 있습니다. 당신은 꽤 파괴적인 호즈족이 그 장소를 소유하기로 결정한 것을 알아챘을 것입니다. 그들의 술 취한 부적절은 조금 통제를 벗어난 것으로 알려져 있습니다. $b $b 가끔 새로운  ⁇ 이 만들어지면 맥주 싸움으로 알려져 있습니다. 맞습니다. $b $b 맥주는 황제 살모를 끌어들이고 난 아직 못 본 것 처럼 무더운게 잡을 수 있어"
rows["559:968960029"]="저는 화공 드루이드 하무엘 루네토메트를 말론 성원의 소화 된 껍데기에 파견했습니다. 그는 전선 뒤에 있습니다. 플라임웨이크라고 알려진 화염된 지형에 있습니다.$B$B하지만 그를 도울 수 있기 전에 서쪽의 에스시나 성당이 안전하고 동물들이 불로부터 구해져 있는지 확인해야 합니다. 그렇지 않으면 모든 것이 손실됩니다."
