rows["572:154140138"]="아카네 리포저는 물체의 마법적 효과를 변형시킬 수 있습니다. 이 마법적으로 복잡한 과정은 단순히 리포저링이라고 알려져 있습니다.$B$B재조합 을 통해, 무기, 장갑, 보석 의 부차적 인 특성 은 추가 한 부차적 인 특성 을 추가 하기 위해 줄일 수 있다. 이 방법 으로, 그 장비 는 그 역할 과 기술 에 가장 잘 맞게 맞게 맞게 조정 될 수 있다.$B$B예를 들어, 만약 어떤 아이템이 여러분의 적을 공격할 수 있는 보너스를 제공했지만 더 빨리 공격하도록 하는 것을 선호한다면, 아카네 리포저는 가격으로 아이템을 다시 부풀려서"
rows["574:335318737"]="읽어주길 바랄게요!\010내 무덤에 서서 울지 마\010난 거기 없어, 난 잠을 잘지 않아\010나는 천개의 바람에 휘어\010노스렌드의 밝은 눈이 넘어서\010나는 부드러운 비가 내리는\010서부 몰락지대의 황금 곡물밭에\010아침이 조용해\010파목거림의 숲, 녹색과 풍요로운\010난 큰 소리를 내며 드럼에 앉아있어요\010나그란드를 가로지르는 거동한 톱니바닥\010나는 빛나는 별들이며\010다르나서스에 대해 부드럽게 꿈꾸는.\010나는 노래하는 새들 속에 있어\010저는 모든 아름다운 일에 참여합니다.\010내 무덤에 서서 울지 마\010난 거기 없어 죽지도 않아\010 "
rows["575:1972483615"]="지금 제가 걱정하는 것은 우리 동쪽의 메너르 호수를 둘러싸고 있는 유적입니다. 수천 년 전, 메너르 아카데미는 미묘한 예술을 처음 연구한 곳 중 하나였습니다. 조용한 호수를 둘러싸고 있는 반지 안에 세워진 아름다운 테라스 구조였으며, 조용한 묵상과 집중적인 연구의 장소였습니다. 바로 그곳에서 제 조상들이 영원의 우물에서 흘러나오는 마법의 에너지의 잠재력을 처음 발견했습니다.$B$B죄송합니다. 너무 많은 걸 받아들이는 건가요? 저는 몇 십 년 동안 신비한 역사에 몰두해 왔고, 다른 사람들이 제 열정을 공유하지 않는다는 것을 잊고 있습니다."
rows["577:1231413696"]="어린 시절, 제 가족 은 제 샴니즘 에 대한 관심 을 승인 하지 않았습니다. 저는 무자비하고 어리석음 이 많았지만, 그것 들 로부터 도망쳐서 혼자 연습 했습니다. 어느 날 집으로 돌아왔을 때, 제 부모 가 사라진 것을 발견했습니다. 제 집 은 파괴 되었습니다. 그 는 누가 그렇게 했는지 결코 찾지 못했습니다.\010저는 제 평생을 제 샤머니즘 비전을 확장하여 과거를 바라보고, 제 가족에게 무슨 일이 일어났는지, 누가 책임지고 있는지 알아내려고 노력했습니다. 저는 훌륭한 길을 걸어왔습니다. 저는 최근 과거에서 일어난 영향력 있는 사건들에 집중하는 것을 배웠지만, 그렇게 오래 전에 일어난 일을 한 번이라도 볼 수 있기를 희망한다면 더 나아가야 합니다."
rows["57:1002176506"]="안녕하세요, 저는 죽은 자 마그 트레이너이고, 당신은 마그입니다."
