rows["591:809841379"]="미친 카오파오는 해를 끼치지 않는다. 정말, 그렇지 않다. 그는 Mogu'shan 궁전 앞의 연못이 소원을 충족시켰다고 들었어요. $b $b 그리고... 그 가난한 사람은 지능을 넘어서 금을 가지고 있습니다. $b $b 유감스럽게도, 주얼 다니오의 가장 좋아하는 음식은 물 위에서 낮은 곳에서 날아다니는 불꽃입니다. $b $b 가난한 사람들이 너무 많은 동전을 삼키지 않았으면 좋겠다 오늘은 주얼 다니오를 얻을 수 있는 날이지만"
rows["595:1728328269"]="우리는 이미 많은 달 동안 영들과 함께 일해 왔지만, 우리 중 많은 사람들이 이미 우리가 전에 봉사했던 영들의 형태를 알고 있습니다.$B$B하지만 살라잔에서 안전하게 지내는 것은 쉽지 않았습니다. 새로운 트릭이 함께 해왔지만, 그들은 할 수 있는 모든 도움을 주면서도, 우리는 몇 년 동안 그의 우두와 정신이없는 종들을 통해 몇 명의 형제 자매를 잃었습니다. 하지만 우리는 섬의 삶을 살려왔고, 볼진과 다크스피어스가 돌아왔을 때, 우리는 살라잔을 어떻게 잡을 수 있는지 알았습니다."
rows["595:1978901291"]="전설에 따르면, 류랑은 거대한 거북이의 등으로 한 번 판다리아를 넘어 바다를 탐험하기 시작했고, 몇 년마다 다시 돌아와 항상 새로운 탐험가를 찾고 함께 여행했습니다. 오늘날까지, 판다렌이 낮을 꿈꾸거나 우주로 향할 때마다 우리는 그들이 \"거북을 기다리고 있는지\" 묻습니다.$b$b대부분의 판다레들은 모험을 별로 좋아하지 않습니다. 그들은 고향과 집 근처에 머물기를 좋아합니다. 하지만 우리 중 일부는 여전히 꿈꾼입니다. 오늘 밤 우리는 남쪽 해안의 거북이 해변에서 바다를 바라보고$b$b'여자 축제'라고 불립니다."
rows["597:301161834"]="<사령관님께서는 계속하기 전에 한눈에 쳐다보며 당신을 고쳐주십니다.>$B$B사실, 대사령부 아비데스 군대가 노스렌드에 도착했을 때, 그녀는 그들의 이름을 스카르렛 오브스트라이트로 바꾸었습니다.$B$B드래곤 플레이지에서 바레안 웨스트윈 대사장이 그녀에게 자신을 소개하는 데 얼마 지나지 않았습니다. 모든 기록에서 그녀는 그를 기대하지 않았으며, 그녀의 권위를 약화시키고 지휘의 제장을 빼앗길 것이라고 기대하지도 않았습니다.$B$B아마 당신이 그녀의 죽음과 관련되어 있었겠지만, 상관없어 그녀가 죽은 후에,"
