rows["59:922775924"]="좀비된 시체를 막기 위해 시체들을 파괴하라!"
rows["59:927336977"]="로크다르 정말 멍청했다! 모고르가 저것보단 훨씬 잘 싸울 수 있었는데!"
rows["59:927414594"]="마을에 거의 다 왔군요. 주위를 잘 살펴보십시오."
rows["59:933048773"]="좋아, 좋아! 싸움은 이제 그만. 누군가 하나가 다칠 필요는 없지."
rows["59:934405429"]="난 공격을 시작할 준비가 돼 있어"
rows["59:937645158"]="이 쇼를 거리로 치고, 망칠게 해 스톰윈드!"
rows["59:942455330"]="다크월 페어는 모든 아웃랜드에서 가장 위대한 이벤트입니다!"
rows["59:946854243"]="괜찮아, 작은 문제야"
rows["59:946988974"]="여보, 따라와 서로 더 잘 알아보자"
rows["59:948230613"]="괴물이 탈출했어 메카토르크의 콧수염으로, 그것은 빨리 있었다!"
rows["59:949533447"]="다시 생각해보면 드라가가 도움이 필요할 수도 있어요!"
rows["59:955635637"]="새로운 주체? 내가 널 조각으로 찢어 버릴거야!"
rows["59:95677292"]="네 작은 지능 내 최고 손톱과 맞지 않는 거야!"
rows["59:957362578"]="우리한테 의지해줄 수 있어, 그 소년 없이는 돌아오지 않을 거야"
rows["59:961968504"]="브루페스트는  ⁇ 을 줄이고 있습니다."
rows["59:971334812"]="이 땅에는 뭔가 있어요."
rows["59:977800157"]="아무것도 아니에요, 폐하. 그저... 폐하가 자랑스러워서요."
rows["59:980619403"]="작은 기부금으로 신학에 대해 훈련할 수 있어요"
rows["59:987775061"]="확신이 없는 시절이었지만, 당신은 내 마음을 편안하게 해주셨습니다."
rows["59:990933507"]="그리고 그 후 노인은 이 세상을 만티드에게 다시 만들 거야!"
rows["59:991390446"]="호드의 이름으로 심심한 박사가 이루어질 것입니다!"
rows["59:991630866"]="타라스를 비켜서 착륙해!"
rows["59:992917500"]="물론입니다, 브란. 잠깐 보호막을 내리겠습니다."
rows["59:993700009"]="%s 남동쪽으로 눈을 돌리고, 당신을 돌아보는 동안 윙윙윙하는 것."
rows["59:995194173"]="라이프파이더, 네가 내 인생을 빼앗길 거야?"
rows["59:995664113"]="다 망할 거야 이제 처음부터 다시 시작해야겠어"
rows["59:996536254"]="플랫폼 아래 비밀 통로가 열렸어요!"
rows["59:998200560"]="다른 사람들과 함께 놔두고 리클레이머 경의 검사를 하러"
